import{_ as a,o as t,c as p,aA as r}from"./chunks/framework.BMzE2Z9R.js";const l=JSON.parse('{"title":"拟态操作","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"other/mimicry_operation.md","filePath":"other/mimicry_operation.md","lastUpdated":1778399398000}'),o={name:"other/mimicry_operation.md"};function i(n,e,_,s,c,m){return t(),p("div",null,[...e[0]||(e[0]=[r('<h1 id="拟态操作" tabindex="-1">拟态操作 <a class="header-anchor" href="#拟态操作" aria-label="Permalink to &quot;拟态操作&quot;">​</a></h1><p>拟态操作可以看作 主动适用 语言对思维反作用的一个应用。</p><p>有点玄学。</p><p>针对脑内或者感觉上的真意的形态，做“处理”</p><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><p>毒瘤，不愿碰。</p><p>就念“斩”字，想象一把刀斩断那个概念真意附近的一切。如果其他地方思考过去，只能看到一面“斩”后的断面。 不要去越过它（断面）</p><p>大片的，已经被激活了。汹涌的太厉害。</p><p>就念“散”字，想象雾散开。意识流从凝聚兴奋状态平息然后散开。</p><p>然后重新看重点在哪，汇集过去。</p><p>散系列的语言，也可以用来遗忘。比起斩 要温和一点。</p><p>还有封装起来，命名曰“封”。相关的思考过去，都碰到“封”字。也不要去拆卡它。</p><p>口渴了，曰“灵泉”啊，“清流”想象画面。</p><p>冷空气慢性咽炎，曰“温润”“阳”“温润如夏”“鸟语花香”平息冷空气刺激咽喉的感觉。拼命理解词语的意义。</p><hr><p>总之就是，用语言对思维的反作用。来一定程度控制自己的思维</p>',16)])])}const h=a(o,[["render",i]]);export{l as __pageData,h as default};
